import { _ as _export_sfc, o as openBlock, c as createElementBlock, a2 as createStaticVNode } from "./chunks/framework.jTK6_58R.js";
const __pageData = JSON.parse('{"title":"Contextory MCP tools","description":"","frontmatter":{},"headers":[],"relativePath":"docs/MCP-TOOLS.md","filePath":"docs/MCP-TOOLS.md"}');
const _sfc_main = { name: "docs/MCP-TOOLS.md" };
function _sfc_render(_ctx, _cache, $props, $setup, $data, $options) {
  return openBlock(), createElementBlock("div", null, [..._cache[0] || (_cache[0] = [
    createStaticVNode('<h1 id="contextory-mcp-tools" tabindex="-1">Contextory MCP tools <a class="header-anchor" href="#contextory-mcp-tools" aria-label="Permalink to &quot;Contextory MCP tools&quot;">\u200B</a></h1><p>Contextory exposes project workflow, retrieval, source tracing, and reporting through a standard stdio MCP server. Agents use these tools from their native conversation; Contextory does not host a second chat or handle model routing.</p><p>Connect through the extension&#39;s provider command rather than assembling private descriptor paths by hand. The project-specific server name is <code>contextory_companion_&lt;project hash&gt;</code>. The authoritative input schemas and descriptions are in <a href="https://github.com/igormicadei/Contextory/blob/v0.7.0/src/contracts/tools.ts" target="_blank" rel="noreferrer">src/contracts/tools.ts</a>; the running server advertises them through MCP <code>tools/list</code>.</p><h2 id="available-tools" tabindex="-1">Available tools <a class="header-anchor" href="#available-tools" aria-label="Permalink to &quot;Available tools&quot;">\u200B</a></h2><p>Project releases add <code>contextory_version_get</code> (global status, paged version commits/semantic records), <code>contextory_release_prepare</code> (concrete plan only) and <code>contextory_release_change</code> (apply/publish/recover/cancel). They are independent of request/spec leases. See <a href="./PROJECT-RELEASES.html">project versions and tags</a> for automatic observation, configuration, durable retries, CLI/CI usage and publication boundaries.</p><p>Version 0.7.0 advertises 36 tools, including project-scoped hook recovery, workspace discovery and coordinated requests. Native proxies and headless stdio MCP use the same schemas:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>contextory_hooks_rebuild</code></td><td>Repair managed hooks and the packaged launcher for an explicit native provider/project using a unique operation ID. Preserves unrelated configuration and native trust; requires a reachable service.</td></tr><tr><td><code>contextory_workspace_get</code></td><td>Discover project identities, canonical roots and attached workspace contexts; optional <code>groupId</code> reads cross-project request branches and aggregate status.</td></tr><tr><td><code>contextory_workspace_request_create</code></td><td>Create linked local requests for explicit <code>projectIds</code>, including the owning server project, with durable original input and idempotent partial recovery.</td></tr><tr><td><code>contextory_project_export</code></td><td>Discover and page stored application-documentation datasets, revisions, history, source facts, check jobs and artifacts, preserving sequence/snapshot and provenance.</td></tr><tr><td><code>contextory_catalog_get</code></td><td>Read file/rule/feature/UI definitions, pending changes and source freshness; optional paged file inventory exposes missing descriptions.</td></tr><tr><td><code>contextory_catalog_change</code></td><td>Create observed definitions or propose replacements/retirements under a spec lease, preserving reason and before/after history.</td></tr><tr><td><code>contextory_catalog_review</code></td><td>Authenticated human UI approval/rejection of an exact baseline/proposal; agents cannot approve.</td></tr><tr><td><code>contextory_catalog_migrate</code></td><td>Resumable file scan and candidate bootstrap for the portable migration agent; never auto-approves candidates.</td></tr><tr><td><code>contextory_codebase_list</code></td><td>List the current project and its isolated local reference registrations.</td></tr><tr><td><code>contextory_codebase_change</code></td><td>Register an authorized absolute local directory (<code>action:add</code>, <code>root</code>, optional <code>name</code>) or detach a reference (<code>action:remove</code>, <code>codebaseId</code>), with an <code>operationId</code>. Source files are untouched.</td></tr><tr><td><code>contextory_code_context_get</code></td><td>Current definitions, dependencies/callers/tests/documents and project memory for <code>query</code>, optional <code>paths</code>/<code>specId</code>, and <code>budgetTokens</code> (512\u20136000, default 3000). Hard JSON byte cap is three times the requested estimate.</td></tr><tr><td><code>contextory_code_architecture_get</code></td><td>Subsystems, dependency counts, entry points, shared symbols and coverage. Default <code>refresh: true</code> checks current files; explicit <code>refresh: false</code> reads the cached snapshot.</td></tr><tr><td><code>contextory_code_path_get</code></td><td>Shortest indexed path from <code>from</code> to <code>to</code>, direction <code>forward</code>/<code>both</code>, bounded by <code>maxDepth</code> (1\u201310). Preserves edge categories and locations.</td></tr><tr><td><code>contextory_code_index_refresh</code></td><td>Refresh the rebuildable projection, or validate/import optional workspace-relative <code>graphifyPath</code>. Does not mutate approved work records.</td></tr></tbody></table><p><code>contextory_search</code> now ranks exact definitions first. <code>contextory_impact_get</code> also accepts a code ID, file, unique symbol or <code>source:path#qualifiedName</code>. Read-only codebase questions do not require tracked work. <a href="./CODEBASE-INTELLIGENCE.html">Examples and limits</a>.</p><p>Every tool accepts optional <code>projectId</code> and <code>workspaceId</code>. Omitted/current project scope stays on that server&#39;s project; it never follows UI selection or an earlier call. Foreign project routing requires current editor workspace membership and preserves the native provider&#39;s role. Multiple attached workspace contexts require explicit <code>workspaceId</code>. Unknown/detached scope fails. Carry project identity with records, artifacts, graph pages and citations. Cross-project requests retain ordinary project-owned milestones, specs, leases and evidence; an unavailable branch makes the aggregate incomplete. Retry creation using its exact original operationId, title, description and projectIds on the original owner.</p><p>Source tools also accept optional <code>codebaseId</code> for isolated references inside the chosen project; omitted or <code>current</code> targets that project&#39;s source. This covers architecture, context, search, impact, path, index/import and flow trace/expand. Paths and source IDs are local to the selected root. Preserve returned codebase identity with citations. References cannot receive workflow mutations. See <a href="./CODEBASE-INTELLIGENCE.html#analyze-reference-codebases">reference examples and limits</a>.</p><p>Both native and headless MCP initialize with shared retrieval/workflow instructions. The workspace brief returns those guidance arrays alongside cached orientation. Start source tasks with scoped code context and inspect current citations; use search for earlier decisions and state, impact/path for connections and flow for calls/branches. Saved changes refresh automatically; re-query relevant context after edits. See the portable <a href="./../skills/contextory-codebase/references/retrieval.html">retrieval reference</a> for bounded results, paging, Graphify recovery and unavailable capabilities. Existing clients may cache an older tool catalog until their native MCP connection reloads.</p><p>Version 0.2.4 adds <code>contextory_usage_get</code> to the native tool list. It reads recorded models and observed token usage, with optional <code>entityId</code> (request/milestone/spec), <code>provider</code>, <code>nativeSessionId</code>, <code>offset</code> and <code>limit</code> filters. Responses include model groups, nulls for unavailable token fields, coverage counts, and paged metadata records. Request-level totals include descendant specs; project-level results also include unassigned observations. This is a read-only record, without billing estimates or transcript access. See <a href="./USER-GUIDE.html#agent-models-and-usage-024">usage capture and provider limits</a>.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>contextory_context_get</code></td><td>Read the workspace brief, active specs, failures, configured checks, and optional focused spec. Start tracked implementation here.</td></tr><tr><td><code>contextory_entity_get</code></td><td>Read a record, immutable historical revision, children, check-job result, or a page of an artifact.</td></tr><tr><td><code>contextory_history_get</code></td><td>Page audit history with readable titles and hierarchy links; optionally scope to a record and its descendants.</td></tr><tr><td><code>contextory_request_change</code></td><td>Create an authorized request or revise it with a reason while preserving original intent.</td></tr><tr><td><code>contextory_spec_change</code></td><td>Create milestones/specs, revise or reopen a spec, block/cancel it, or request verified completion.</td></tr><tr><td><code>contextory_session_attach</code></td><td>Register a native session for correlation; return the Contextory session ID.</td></tr><tr><td><code>contextory_spec_lease</code></td><td>Claim, renew, or release the active implementation lease for a spec/session.</td></tr><tr><td><code>contextory_finding_record</code></td><td>Record/update an issue, its impact, resolution, blocking status, and source references.</td></tr><tr><td><code>contextory_decision_record</code></td><td>Retain a choice, rationale, alternatives, consequences, sources, and optional superseded decision.</td></tr><tr><td><code>contextory_evidence_record</code></td><td>Record external/manual evidence and criterion links, with its reported origin preserved.</td></tr><tr><td><code>contextory_check_run</code></td><td>Run a named configured recipe independently; return an asynchronous check job.</td></tr><tr><td><code>contextory_outcome_submit</code></td><td>Persist changes, issue/decision summaries, validation mappings, limits, report/changelog text, and optional commits. Return the next completion action.</td></tr><tr><td><code>contextory_search</code></td><td>Retrieve current project records and indexed source through lexical, semantic, or hybrid search.</td></tr><tr><td><code>contextory_relationship_change</code></td><td>Link records, or associate a record with a workspace file/symbol, with a relationship kind and rationale.</td></tr><tr><td><code>contextory_impact_get</code></td><td>Traverse relationships forward, reverse, or both, returning readable summaries and explicit limits.</td></tr><tr><td><code>contextory_flow_trace</code></td><td>Trace supported source calls/control flow from a symbol or position, with bounded depth, fanout, size, and time.</td></tr><tr><td><code>contextory_flow_expand</code></td><td>Read a stored graph page or expand a frontier while checking the source snapshot.</td></tr><tr><td><code>contextory_report_export</code></td><td>Export one request&#39;s full report, completed-work changelog, or JSON records.</td></tr></tbody></table><h2 id="mutation-and-session-rules" tabindex="-1">Mutation and session rules <a class="header-anchor" href="#mutation-and-session-rules" aria-label="Permalink to &quot;Mutation and session rules&quot;">\u200B</a></h2><p>See <a href="./PROJECT-KNOWLEDGE.html">governed knowledge and documentation</a> for catalog schemas, human review, migration, export sections, pagination and enforcement limits. When a catalog exists, outcomes include <code>catalog:{recordIds,explanation}</code>; pending proposals and stale affected approved definitions block completion.</p><p>Pass the exact <code>nativeSessionId</code> supplied in Contextory&#39;s hook reminder when calling <code>contextory_session_attach</code>. This enables automatic association of native model/usage observations with a single active spec lease. Omit the ID when unavailable; do not invent it or infer token counts. Session/model routing and conversation history remain native.</p><ul><li>Read existing records before editing them. Operations on existing versioned records require their current <code>expectedRevision</code>; resolve conflicts by rereading.</li><li>Each mutation takes an <code>operationId</code> of 8\u2013160 characters. Use a new ID for a new operation and reuse the same ID for a retry of that operation.</li><li>Create milestones under requests and specs under milestones. Specs require acceptance criteria. Do not create requests for ordinary questions or expand user scope silently.</li><li>Attach the native session, then claim a spec with that returned Contextory session ID. Findings, decisions, evidence, checks, and outcomes require the returned lease ID. Leases last 30 minutes; renew them during long work.</li><li>Record concise explanations that a developer can evaluate later. Preserve uncertainty and distinguish agent-authored choices from observed developer decisions.</li><li>Contextory tools do not grant native permissions or authorize extra work. Check recipes are configured through trusted editor settings rather than arbitrary MCP command execution.</li></ul><h2 id="complete-a-spec-correctly" tabindex="-1">Complete a spec correctly <a class="header-anchor" href="#complete-a-spec-correctly" aria-label="Permalink to &quot;Complete a spec correctly&quot;">\u200B</a></h2><ol><li>Read <code>contextory_context_get</code> and inspect the current spec/criteria.</li><li>Register the native session and claim its spec lease.</li><li>Retrieve prior decisions and inspect relevant relationships/source flow. Implement with native editing tools and record findings and decisions as work proceeds.</li><li>Use <code>contextory_check_run</code> with a configured <code>recipeId</code>, criterion IDs, spec ID, and lease ID. Poll the returned job through <code>contextory_entity_get</code> until it finishes. Keep the actual result/evidence IDs.</li><li>Submit <code>contextory_outcome_submit</code> with the current revision and exactly one evidence mapping for every current criterion. Include changes, issue/fix and decision summaries, validation, limitations, report text, and changelog text. Explicitly state when there were no findings or new decisions.</li><li>Use the outcome response&#39;s next action: <code>contextory_spec_change</code> with <code>action: &quot;complete&quot;</code>, the spec ID, returned revision, and a new operation ID. Confirm <code>state: &quot;completed&quot;</code> in the result.</li></ol><p>Outcome submission alone leaves the spec open. Completion rejects stale source/contract/attempt evidence, later failures, pending checks, unresolved blocking findings, or incomplete dependencies. Resolve the blocker or explain it to the user. Verified completion rolls up milestone/request state; new planned work and reopen operations reopen the affected parents.</p><p>An outcome is a durable explanation, not permission to overwrite evidence provenance or a shortcut around check requirements. See the <a href="./SPEC-OUTCOME-TEMPLATE.html">outcome template</a> and <a href="./USER-GUIDE.html#configure-checks">check configuration</a>.</p><h2 id="read-only-examples" tabindex="-1">Read-only examples <a class="header-anchor" href="#read-only-examples" aria-label="Permalink to &quot;Read-only examples&quot;">\u200B</a></h2><p>These are MCP tool argument objects. Replace illustrative paths and record IDs with values returned by the current workspace.</p><p>Search earlier decisions and changes:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;checkout retry idempotency&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hybrid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Call <code>contextory_search</code> with that object. Hybrid mode explicitly falls back to lexical retrieval if the optional model is unavailable; semantic-only mode reports its unavailability. Record results cite current revisions. To read a historical version, use <code>contextory_entity_get</code> with <code>id</code> and <code>revision</code>.</p><p>Trace Python source with <code>contextory_flow_trace</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;root&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/checkout.py&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;symbol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;checkout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;view&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;flow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;direction&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;outgoing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;limits&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;callDepth&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;nodes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;edges&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timeoutMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Positions and source references use zero-based lines/characters. Python tracing works through the agent service without an editor language provider. Other languages may rely on the installed editor call-hierarchy provider. Static results expose unresolved targets and traversal boundaries; they are not runtime evidence.</p><p>Explore a request&#39;s relationships using <code>contextory_impact_get</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;REQ-example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;direction&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;both&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;depth&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="history-graphs-artifacts-and-reports" tabindex="-1">History, graphs, artifacts, and reports <a class="header-anchor" href="#history-graphs-artifacts-and-reports" aria-label="Permalink to &quot;History, graphs, artifacts, and reports&quot;">\u200B</a></h2><p><code>contextory_history_get</code> defaults to 40 events. Pass the response&#39;s <code>nextBefore</code> as <code>before</code> to retrieve older events. <code>entityId</code> scopes history to that request/milestone/spec and its descendants.</p><p>Large responses can return <code>ART-</code> artifact handles instead of the full result. Use <code>contextory_entity_get</code> with the handle and <code>offset</code>/<code>limit</code> to retrieve more; artifact offsets count 400-character pages, while entity-child offsets count records. Graph paging uses <code>contextory_flow_expand</code>, <code>graphId</code>, and <code>snapshotId</code>. Source changes invalidate expansion handles rather than combining different source snapshots.</p><p>Export one request with <code>contextory_report_export</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requestId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;REQ-example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;format&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;report&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use <code>&quot;changelog&quot;</code> for completed-spec changelog entries or <code>&quot;json&quot;</code> for the scoped records. Reports include the request and descendants rather than unrelated workspace activity. Follow the returned artifact handle for the full content.</p><h2 id="qualification" tabindex="-1">Qualification <a class="header-anchor" href="#qualification" aria-label="Permalink to &quot;Qualification&quot;">\u200B</a></h2><p>Automated coverage exercises the actual stdio MCP bridge, all tool definitions, role isolation, descriptor rotation, and a full create/claim/check/outcome/complete/read workflow. Actual editor-host tests generate all three provider configurations. Authenticated model-driven conversations, provider-native trust/reload behavior, and a model following the workflow remain separate qualification steps. See <a href="./VALIDATION.html">VALIDATION.md</a>.</p>', 39)
  ])]);
}
